INSERT INTO ctl_comm_mechanism(key,name,transport,gcode_passthrough,passthrough_ref,auth,orca_verified,notes) VALUES ('bambu_mqtt','Bambu Lab MQTT','mqtt',TRUE,'gcode_line tunnel {"print":{"command":"gcode_line"}} (DeviceManager.cpp:4650)','LAN access code / cloud token',TRUE,'Structured JSON commands preferred; gcode_line fallback. Topic device/{id}/request (in closed BambuNetwork plugin).');
INSERT INTO ctl_comm_mechanism(key,name,transport,gcode_passthrough,passthrough_ref,auth,orca_verified,notes) VALUES ('moonraker','Moonraker (Klipper)','http_rest',TRUE,'POST /printer/gcode/script (Moonraker API; NOT used by Orca itself)','X-Api-Key optional (often none on LAN)',TRUE,'Orca only does upload+print/start (Moonraker.cpp); full gcode passthrough exists in Moonraker and is how OpenPrintHQ drives it.');
INSERT INTO ctl_comm_mechanism(key,name,transport,gcode_passthrough,passthrough_ref,auth,orca_verified,notes) VALUES ('octoprint','OctoPrint (Marlin serial bridge)','http_rest',TRUE,'POST /api/printer/command (OctoPrint API; NOT used by Orca)','X-Api-Key header (OctoPrint.cpp:497)',TRUE,'Orca is upload-only; OctoPrint''s own API supports gcode passthrough + temp control.');
INSERT INTO ctl_comm_mechanism(key,name,transport,gcode_passthrough,passthrough_ref,auth,orca_verified,notes) VALUES ('prusalink','PrusaLink / PrusaConnect','http_rest',FALSE,NULL,'X-Api-Key or HTTP Digest (OctoPrint.cpp:569)',TRUE,'Upload + print flag only (PUT api/v1/files). No gcode passthrough exposed.');
INSERT INTO ctl_comm_mechanism(key,name,transport,gcode_passthrough,passthrough_ref,auth,orca_verified,notes) VALUES ('duet_rrf','Duet / RepRapFirmware','http_rest',TRUE,'GET rr_gcode?gcode=... | POST machine/code (Duet.cpp:247-251)','password via rr_connect (Duet.cpp:206)',TRUE,'Full arbitrary G-code over HTTP.');
INSERT INTO ctl_comm_mechanism(key,name,transport,gcode_passthrough,passthrough_ref,auth,orca_verified,notes) VALUES ('repetier','Repetier-Server','http_rest',FALSE,NULL,'X-Api-Key (Repetier.cpp:179)',TRUE,'Orca upload+autostart only; Repetier-Server has its own gcode API.');
INSERT INTO ctl_comm_mechanism(key,name,transport,gcode_passthrough,passthrough_ref,auth,orca_verified,notes) VALUES ('mks_tcp','MKS WiFi (raw TCP)','tcp_console',TRUE,'raw G/M-code over TCP :8080 (MKS.cpp)','none',TRUE,'Raw serial console; any gcode.');
INSERT INTO ctl_comm_mechanism(key,name,transport,gcode_passthrough,passthrough_ref,auth,orca_verified,notes) VALUES ('flashforge_tcp','FlashForge (raw TCP ~M)','tcp_console',TRUE,'~M-codes over TCP :8899 (Flashforge.hpp:56)','serial#/checkCode (HTTP variant)',TRUE,'Legacy serial console; HTTP :8898 variant is JSON-only.');
INSERT INTO ctl_comm_mechanism(key,name,transport,gcode_passthrough,passthrough_ref,auth,orca_verified,notes) VALUES ('esp3d','ESP3D bridge','http_rest',TRUE,'GET /command?plain=<gcode> (ESP3D.cpp)','none',TRUE,'HTTP-to-serial bridge; arbitrary gcode.');
INSERT INTO ctl_comm_mechanism(key,name,transport,gcode_passthrough,passthrough_ref,auth,orca_verified,notes) VALUES ('creality_ws','CrealityPrint (K-series)','websocket',FALSE,NULL,'Bearer token (CrealityPrint.cpp:68)',TRUE,'WS :9999 fixed verbs (opGcodeFile); no raw gcode via Orca path. Underlying Klipper does.');
INSERT INTO ctl_comm_mechanism(key,name,transport,gcode_passthrough,passthrough_ref,auth,orca_verified,notes) VALUES ('elegoo_sdcp','ElegooLink SDCP','websocket',FALSE,NULL,'X-Token (ElegooLink.cpp)',TRUE,'WS :3030 SDCP command codes only (START_PRINT=128).');
INSERT INTO ctl_comm_mechanism(key,name,transport,gcode_passthrough,passthrough_ref,auth,orca_verified,notes) VALUES ('marlin_serial','Marlin over USB serial','serial',TRUE,'raw G-code over serial','none',FALSE,'Generic serial (not an Orca network host); firmware accepts standard Marlin gcode.');
